R('parking',s=>{let st={x:100,y:375,a:-Math.PI/2,v:0,hold:0},ob={x:190,y:220,w:85,h:140};return{state:st,update(dt){let old={x:st.x,y:st.y};if(s.keys.ArrowLeft)st.a-=1.6*dt;if(s.keys.ArrowRight)st.a+=1.6*dt;if(s.keys.ArrowUp)st.v+=95*dt;if(s.keys.ArrowDown)st.v-=100*dt;st.v*=Math.pow(.23,dt);st.v=s.clamp(st.v,-75,125);st.x+=Math.cos(st.a)*st.v*dt;st.y+=Math.sin(st.a)*st.v*dt;st.x=s.clamp(st.x,25,455);st.y=s.clamp(st.y,85,455);if(st.x>ob.x-18&&st.x<ob.x+ob.w+18&&st.y>ob.y-25&&st.y<ob.y+ob.h+25){st.x=old.x;st.y=old.y;st.v*= -.25}let angle=Math.atan2(Math.sin(st.a+Math.PI/2),Math.cos(st.a+Math.PI/2));if(st.x>330&&st.x<400&&st.y>120&&st.y<190&&Math.abs(st.v)<14&&Math.abs(angle)<.35)st.hold+=dt;else st.hold=0;if(st.hold>1)s.win()},draw(){s.rect(20,70,440,395,'#32473b',15);s.rect(310,88,110,145,'#52754e',10);s.ctx.setLineDash([10,7]);s.line(320,100,320,222,s.pal.lime,3);s.line(410,100,410,222,s.pal.lime,3);s.ctx.setLineDash([]);s.arrow(365,125,-Math.PI/2,s.pal.lime);s.rect(ob.x,ob.y,ob.w,ob.h,'#9d7860',12);s.ctx.save();s.ctx.translate(st.x,st.y);s.ctx.rotate(st.a+Math.PI/2);s.rect(-18,-30,36,60,s.pal.gold,9);s.rect(-12,-17,24,17,'#375452',4);s.ctx.restore();s.label(`Остановись в зоне ↑  ·  скорость ${Math.round(Math.abs(st.v))}`)}}});
R('mines',s=>{let st={mines:[],open:[],flags:[],generated:false,flagMode:false};function generate(i){let c=i%5,r=Math.floor(i/5),choices=Array.from({length:25},(_,j)=>j).filter(j=>Math.abs(j%5-c)>1||Math.abs(Math.floor(j/5)-r)>1);st.mines=s.shuffle(choices).slice(0,4);st.generated=true}function adjacent(i){let x=i%5,y=Math.floor(i/5);return Array.from({length:25},(_,j)=>j).filter(j=>j!==i&&Math.abs(j%5-x)<=1&&Math.abs(Math.floor(j/5)-y)<=1)}function reveal(i){if(st.open.includes(i)||st.flags.includes(i))return;st.open.push(i);if(!adjacent(i).some(j=>st.mines.includes(j)))for(let j of adjacent(i))if(!st.mines.includes(j))reveal(j)}return{state:st,tap(x,y){let p=s.tileAt(x,y,5,5,60,90,84);if(!p||st.open.includes(p.i))return;if(st.flagMode){let i=st.flags.indexOf(p.i);if(i<0)st.flags.push(p.i);else st.flags.splice(i,1);return}if(!st.generated)generate(p.i);if(st.mines.includes(p.i)){s.lose('Попалась мина. Первый ход безопасен; дальше помогают числа.');return}reveal(p.i);if(st.open.length===21)s.win()},draw(){s.grid(5,5,60,90,84,(x,y,a,b,c)=>{let i=y*5+x,open=st.open.includes(i);s.rect(a+2,b+2,c-4,c-4,open?'#cee0b7':'#3b5c46',8);if(open){let n=adjacent(i).filter(j=>st.mines.includes(j)).length;if(n)s.text(n,a+c/2,b+c/2,24,'#254c43')}else if(st.flags.includes(i))s.text('⚑',a+c/2,b+c/2,24,s.pal.gold)});s.button(130,410,220,42,st.flagMode?'⚑ Режим флажков':'Открывать клетки',()=>st.flagMode=!st.flagMode,st.flagMode?'#775b36':'#385d46');s.label(`Безопасных клеток: ${st.open.length}/21`)}}});
R('curling',s=>{let st={x:240,y:410,vx:0,vy:0,drag:false,throws:0,score:0,moving:false,settle:0};return{state:st,down(x,y){if(!st.moving&&Math.hypot(x-st.x,y-st.y)<40)st.drag=true},up(x,y){if(st.drag){st.vx=s.clamp((st.x-x)*8,-600,600);st.vy=s.clamp((st.y-y)*8,-700,100);st.drag=false;st.moving=true;st.throws++;st.settle=0}},update(dt){if(!st.moving)return;st.x+=st.vx*dt;st.y+=st.vy*dt;st.vx*=Math.exp(-2*dt);st.vy*=Math.exp(-2*dt);if(st.x<40||st.x>440){st.x=s.clamp(st.x,40,440);st.vx*=-.6}if(st.y<75){st.y=75;st.vy*=-.4}if(Math.hypot(st.vx,st.vy)<8){st.settle+=dt;if(st.settle>.4){let d=Math.hypot(st.x-240,st.y-180);st.score+=d<23?8:d<47?5:d<83?3:0;if(st.score>=12)s.win();else if(st.throws>=4)s.lose(`Набрано ${st.score}/12. Чуть измени силу броска.`);st.x=240;st.y=410;st.vx=st.vy=0;st.moving=false}}},draw(){s.rect(28,65,424,400,'#c9e7dd',22);for(let [r,c] of [[85,'#799faf'],[58,'#e6efe6'],[32,'#df9489'],[14,'#c4d8b7']])s.circle(240,180,r,c);if(st.drag)s.line(st.x,st.y,s.pointer.x,s.pointer.y,'#435f55',3);s.circle(st.x,st.y,16,'#596f67');s.rect(st.x-8,st.y-8,16,6,s.pal.gold,3);s.label(`Очки ${st.score}/12  ·  бросок ${Math.min(st.throws+1,4)}/4`)}}});
