function flips(board,i,side){if(board[i])return[];let result=[];for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++){if(!dx&&!dy)continue;let x=i%4+dx,y=Math.floor(i/4)+dy,chain=[];while(x>=0&&x<4&&y>=0&&y<4&&board[y*4+x]===-side){chain.push(y*4+x);x+=dx;y+=dy}if(chain.length&&x>=0&&x<4&&y>=0&&y<4&&board[y*4+x]===side)result.push(...chain)}return result}
R('reversi',s=>{let st={board:Array(16).fill(0),turn:1,wait:0};st.board[5]=st.board[10]=-1;st.board[6]=st.board[9]=1;function moves(side){return st.board.map((v,i)=>({i,f:flips(st.board,i,side)})).filter(m=>m.f.length)}function place(i,side){let f=flips(st.board,i,side);if(!f.length)return false;st.board[i]=side;for(let j of f)st.board[j]=side;return true}function finish(){let you=st.board.filter(x=>x===1).length,bot=st.board.filter(x=>x===-1).length;if(you>bot)s.win();else s.lose(`Бот набрал ${bot}, ты — ${you}. Попробуй захватывать углы.`)}return{state:st,tap(x,y){if(st.turn!==1)return;let p=s.tileAt(x,y,4,4,85,70,80);if(p&&place(p.i,1)){st.turn=-1;st.wait=.5}},update(dt){if(st.turn===-1){st.wait-=dt;if(st.wait>0)return;let m=moves(-1);if(m.length){m.sort((a,b)=>b.f.length-a.f.length);place(m[0].i,-1)}let yours=moves(1);if(yours.length)st.turn=1;else if(moves(-1).length)st.wait=.5;else finish()}else if(!moves(1).length){if(moves(-1).length){st.turn=-1;st.wait=.5}else finish()}},draw(){s.grid(4,4,85,70,80,(x,y,a,b,c)=>{let i=y*4+x;s.rect(a+2,b+2,c-4,c-4,'#3b6047',7);if(st.board[i])s.circle(a+c/2,b+c/2,29,st.board[i]===1?s.pal.lime:'#233b35');else if(st.turn===1&&flips(st.board,i,1).length)s.circle(a+c/2,b+c/2,7,s.pal.gold)});s.label(`Ты: ${st.board.filter(v=>v===1).length}  ·  бот: ${st.board.filter(v=>v===-1).length}`);s.text(st.turn===1?'Твой ход: золотые точки':'Бот думает…',240,452,16,s.pal.muted)}}});
R('logistics',s=>{const nodes=[{x:80,y:130},{x:240,y:130},{x:400,y:130},{x:80,y:295},{x:240,y:295},{x:400,y:295},{x:240,y:420}],edges=[[0,1],[1,2],[0,3],[1,4],[2,5],[3,4],[4,5],[4,6]],dest=[0,2,6];let st={node:4,to:null,progress:0,round:0,loaded:true,fuel:7};return{state:st,tap(x,y){if(st.to!==null)return;let i=nodes.findIndex(n=>s.dist(n,{x,y})<37);if(i>=0&&edges.some(e=>e.includes(i)&&e.includes(st.node))){st.to=i;st.progress=0}},update(dt){if(st.to===null)return;st.progress+=dt/1.1;if(st.progress>=1){st.node=st.to;st.to=null;st.fuel--;if(st.node===4){st.loaded=true;st.fuel=7}if(st.loaded&&st.node===dest[st.round]){st.loaded=false;if(++st.round===3)s.win()}if(st.fuel<=0)s.lose('Топливо кончилось. На складе бак заправляется автоматически.')}},draw(){for(let [a,b]of edges)s.line(nodes[a].x,nodes[a].y,nodes[b].x,nodes[b].y,'#779778',9);nodes.forEach((p,i)=>{s.circle(p.x,p.y,29,i===4?'#759a5e':i===dest[st.round]&&st.loaded?s.pal.gold:'#375343');s.text(i===4?'СКЛАД':String(i+1),p.x,p.y,11,i===dest[st.round]?s.pal.bg:s.pal.white)});let a=nodes[st.node],b=st.to===null?a:nodes[st.to],f=st.to===null?0:st.progress;s.rect(a.x+(b.x-a.x)*f-13,a.y+(b.y-a.y)*f-10,26,20,s.pal.blue,5);s.label(`Доставлено ${st.round}/3  ·  топливо ${st.fuel}`);s.text(st.loaded?'Вези посылку к золотому адресу':'Вернись на склад за посылкой',240,64,13,s.pal.muted)}}});
R('siege',s=>{let st={angle:45,power:230,enemy:3,hp:5,ball:null,turn:0,shots:0};function fire(){if(st.ball||st.turn>0)return;let a=st.angle*Math.PI/180;st.ball={x:65,y:390,vx:Math.cos(a)*st.power,vy:-Math.sin(a)*st.power};st.shots++}return{state:st,update(dt){if(st.turn>0){st.turn-=dt;if(st.turn<=0){st.hp--;if(st.hp<=0)s.lose('Бот выиграл дуэль. Попробуй угол около 45° и силу около 260.')}}let b=st.ball;if(!b)return;b.vy+=180*dt;b.x+=b.vx*dt;b.y+=b.vy*dt;if(Math.hypot(b.x-395,b.y-360)<39){st.enemy--;st.ball=null;if(st.enemy<=0)s.win();else st.turn=.7}else if(b.x>480||b.y>435||b.y<40){st.ball=null;st.turn=.7}},draw(){floor(s,420);s.rect(35,355,55,65,s.pal.lime,6);s.rect(370,320,55,100,s.pal.red,6);s.line(65,390,65+Math.cos(st.angle*Math.PI/180)*40,390-Math.sin(st.angle*Math.PI/180)*40,s.pal.gold,9);if(st.ball)s.circle(st.ball.x,st.ball.y,8,s.pal.gold);s.label(`Твоя крепость ${st.hp}  ·  враг ${st.enemy}`);s.text(`Угол ${st.angle}°   Сила ${st.power}`,240,90,19);s.button(20,125,90,45,'Угол −',()=>st.angle=Math.max(15,st.angle-5));s.button(120,125,90,45,'Угол +',()=>st.angle=Math.min(75,st.angle+5));s.button(250,125,95,45,'Сила −',()=>st.power=Math.max(130,st.power-15));s.button(355,125,105,45,'Сила +',()=>st.power=Math.min(380,st.power+15));s.button(165,190,150,48,st.ball?'Летит…':'ОГОНЬ',fire,'#806844')}}});
R('lanes',s=>{let st={gold:30,selected:0,units:[],bot:4,hp:5,enemy:5,spawn:0};const beats=[1,2,0],icons=['⚔','➶','✦'];function spawn(lane){if(st.gold<12)return;st.gold-=12;st.units.push({x:60,lane,type:st.selected,side:1,hp:10})}return{state:st,tap(x,y){if(y>110&&y<365){let lane=Math.floor((y-110)/85);if(lane>=0&&lane<3)spawn(lane)}},update(dt){st.gold+=3.3*dt;st.bot-=dt;if(st.bot<=0){st.bot=5;st.units.push({x:420,lane:Math.floor(s.rand()*3),type:Math.floor(s.rand()*3),side:-1,hp:9})}for(let u of st.units){let foe=st.units.find(v=>v.side!==u.side&&v.lane===u.lane&&v.hp>0&&Math.abs(u.x-v.x)<28);if(foe)foe.hp-=(beats[u.type]===foe.type?9:beats[foe.type]===u.type?2:5)*dt;else u.x+=u.side*34*dt;if(u.x>425){st.enemy--;u.hp=0}if(u.x<55){st.hp--;u.hp=0}}st.units=st.units.filter(u=>u.hp>0);if(st.enemy<=0)s.win();if(st.hp<=0)s.lose('Противник прорвался. Выбирай подходящие контр-войска.')},draw(){for(let lane=0;lane<3;lane++){s.rect(35,115+lane*85,410,68,'#2c493b',12);s.text('+',58,150+lane*85,24,s.pal.lime)}for(let u of st.units){s.circle(u.x,150+u.lane*85,16,u.side===1?s.pal.blue:s.pal.red);s.text(icons[u.type],u.x,150+u.lane*85,17,s.pal.bg)}for(let i=0;i<3;i++)s.button(35+i*140,400,130,48,`${icons[i]} · 12`,()=>st.selected=i,st.selected===i?'#71894c':'#385343');s.label(`Золото ${Math.floor(st.gold)}  ·  твоя база ${st.hp}  ·  враг ${st.enemy}`)}}});
R('farm',s=>{const crop=['Морковь','Пшеница','Тыква'],dur=[6,8,10],icons=['◆','♜','●'];let st={plots:Array.from({length:6},()=>({type:-1,progress:0,wet:0})),selected:0,water:4,inventory:[0,0,0],order:0},orders=[{type:0,n:2},{type:1,n:2},{type:2,n:1}];return{state:st,tap(x,y){let p=s.tileAt(x,y,3,2,115,67.5,115);if(!p)return;let plot=st.plots[p.i];if(plot.type<0){plot.type=st.selected;plot.progress=0;plot.wet=0}else if(plot.progress>=dur[plot.type]){st.inventory[plot.type]++;plot.type=-1;let o=orders[st.order];if(st.inventory[o.type]>=o.n){st.inventory[o.type]-=o.n;if(++st.order===3)s.win();else st.selected=orders[st.order].type}}else if(st.water>=1){st.water--;plot.wet=8}},update(dt){st.water=Math.min(6,st.water+dt*.35);for(let p of st.plots)if(p.type>=0&&p.wet>0){p.wet-=dt;p.progress=Math.min(dur[p.type],p.progress+dt)}},draw(){let o=orders[Math.min(st.order,2)];s.label(`Заказ ${st.order+1}/3: ${crop[o.type]} ×${o.n}  ·  вода ${Math.floor(st.water)}`);s.grid(3,2,115,67.5,115,(x,y,a,b,c)=>{let p=st.plots[y*3+x];s.rect(a+5,b+5,c-10,c-10,p.wet>0?'#6d6444':'#675039',14);if(p.type>=0){s.text(icons[p.type],a+c/2,b+c/2,34,p.progress>=dur[p.type]?s.pal.gold:'#9dc46a');s.rect(a+13,b+c-18,(c-26)*p.progress/dur[p.type],6,s.pal.lime,2);if(p.wet<=0&&p.progress<dur[p.type])s.text('💧',a+c-23,b+25,18)}else s.text('+',a+c/2,b+c/2,30,'#bba47b')});for(let i=0;i<3;i++)s.button(25+i*150,390,140,48,crop[i],()=>st.selected=i,st.selected===i?'#72884d':'#3e5d45');s.text('Посадить → полить → дождаться → собрать',240,455,12,s.pal.muted)}}});
