R('conquest',s=>{let st={nodes:[{x:60,y:245,owner:1,n:30},{x:170,y:130,owner:0,n:5},{x:170,y:365,owner:0,n:5},{x:290,y:245,owner:0,n:7},{x:390,y:110,owner:0,n:5},{x:420,y:250,owner:-1,n:13},{x:390,y:400,owner:-1,n:13}],troops:[],selected:null,bot:8};function send(a,b,side){let n=st.nodes[a],count=Math.floor(n.n/2);if(count<1||a===b)return;n.n-=count;st.troops.push({from:a,to:b,x:n.x,y:n.y,n:count,side})}return{state:st,tap(x,y){let i=st.nodes.findIndex(n=>s.dist(n,{x,y})<35);if(i<0)return;if(st.selected===null){if(st.nodes[i].owner===1)st.selected=i}else{send(st.selected,i,1);st.selected=null}},update(dt){for(let n of st.nodes)if(n.owner)n.n+=dt*(n.owner===1?1.1:.36);st.bot-=dt;if(st.bot<=0){st.bot=8;let own=st.nodes.map((n,i)=>({...n,i})).filter(n=>n.owner===-1),targets=st.nodes.map((n,i)=>({...n,i})).filter(n=>n.owner!==-1);if(own.length&&targets.length){own.sort((a,b)=>b.n-a.n);targets.sort((a,b)=>a.n-b.n);send(own[0].i,targets[0].i,-1)}}for(let t of st.troops){let p=st.nodes[t.to],d=s.dist(t,p);if(d<7){if(p.owner===t.side)p.n+=t.n;else{p.n-=t.n;if(p.n<0){p.n=-p.n;p.owner=t.side}}t.done=true}else{t.x+=(p.x-t.x)/d*90*dt;t.y+=(p.y-t.y)/d*90*dt}}st.troops=st.troops.filter(t=>!t.done);if(st.nodes.every(n=>n.owner!==-1))s.win();if(!st.nodes.some(n=>n.owner===1)&&!st.troops.some(t=>t.side===1))s.lose('Все твои башни потеряны. Сначала усили доход нейтральными башнями.')},draw(){for(let t of st.troops){s.circle(t.x,t.y,10,t.side===1?s.pal.blue:s.pal.red);s.text(t.n,t.x,t.y,10,s.pal.bg)}st.nodes.forEach((n,i)=>{if(st.selected===i)s.circle(n.x,n.y,38,s.pal.gold);s.circle(n.x,n.y,30,n.owner===1?s.pal.lime:n.owner===-1?s.pal.red:'#7c8d73');s.text(Math.floor(n.n),n.x,n.y,21,s.pal.bg)});s.label('Выбери свою башню → нажми на цель')}}});
R('stealth',s=>{const rows=['########','#......#','#..#...#','#......#','#.#....#','#......#','########'];let map=tileGame(s,rows,1,5),st=map.state;st.turn=0;st.docs=[{x:2,y:1,got:false},{x:5,y:3,got:false},{x:6,y:5,got:false}];const routes=[[{x:4,y:1},{x:5,y:1},{x:6,y:1},{x:6,y:2},{x:5,y:2},{x:4,y:2}],[{x:4,y:4},{x:5,y:4},{x:6,y:4},{x:6,y:3},{x:5,y:3},{x:4,y:3}]];function guards(){return routes.map((r,i)=>{let p=r[st.turn%r.length],next=r[(st.turn+1)%r.length];return{...p,dx:Math.sign(next.x-p.x),dy:Math.sign(next.y-p.y)}})}function step(k){let d=direction(k);if(!d&&k!=='Space')return;if(d){let x=st.x+d[0],y=st.y+d[1];if(rows[y]?.[x]!=='.')return;st.x=x;st.y=y}st.turn++;for(let p of st.docs)if(p.x===st.x&&p.y===st.y)p.got=true;for(let g of guards()){if(g.x===st.x&&g.y===st.y){s.lose('Стражник оказался рядом. Следи за его следующим ходом.');return}for(let a=1;a<=2;a++){let x=g.x+g.dx*a,y=g.y+g.dy*a;if(rows[y]?.[x]!=='.')break;if(st.x===x&&st.y===y){s.lose('Тебя заметили. Пробел позволяет дождаться удобного момента.');return}}}if(st.docs.every(p=>p.got)&&st.x===6&&st.y===1)s.win()}let game={state:st,key:step,draw(){map.draw();for(let g of guards()){for(let a=1;a<=2;a++){let x=g.x+g.dx*a,y=g.y+g.dy*a;if(rows[y]?.[x]!=='.')break;let p=map.pos(x,y);s.rect(p.x-21,p.y-21,42,42,'#754d3c',4)}let p=map.pos(g.x,g.y);s.arrow(p.x,p.y,Math.atan2(g.dy,g.dx),s.pal.red,18)}for(let p of st.docs)if(!p.got){let q=map.pos(p.x,p.y);s.rect(q.x-10,q.y-13,20,26,s.pal.gold,3)}let exit=map.pos(6,1);s.text('⚑',exit.x,exit.y,24,s.pal.lime);let p=map.pos(st.x,st.y);s.cat(p.x,p.y,14);s.label(`Документы ${st.docs.filter(d=>d.got).length}/3  ·  ход ${st.turn}`)}};return swipe(game)});
R('anagram',s=>{const words=['ПОРТАЛ','КОРОНА','МОЛНИЯ'],hints=['Проход между далёкими местами','Украшение на голове монарха','Яркий электрический разряд в небе'];let st={round:0,letters:s.shuffle([...words[0]]),picked:[]};return{state:st,tap(x,y){let p=s.tileAt(x,y,6,1,64,48,285);if(!p||st.picked.includes(p.i))return;st.picked.push(p.i);if(st.picked.length===6){let word=st.picked.map(i=>st.letters[i]).join('');if(word===words[st.round]){if(++st.round===3)s.win();else{st.letters=s.shuffle([...words[st.round]]);st.picked=[]}}}},draw(){s.label(`Слово ${st.round+1}/3`);s.text(hints[Math.min(st.round,2)],240,115,16,s.pal.gold);for(let i=0;i<6;i++){s.rect(48+i*64,175,57,65,'#365440',10);if(st.picked[i]!==undefined)s.text(st.letters[st.picked[i]],76.5+i*64,207,27,s.pal.lime)}st.letters.forEach((v,i)=>{s.rect(48+i*64,285,57,65,st.picked.includes(i)?'#20382d':'#66804f',10);if(!st.picked.includes(i))s.text(v,76.5+i*64,317,27)});s.button(140,390,200,45,'Вернуть букву',()=>st.picked.pop())}}});
