R('docking',s=>{let st={x:95,y:385,vx:0,vy:0,a:-Math.PI/2,hold:0};return{state:st,update(dt){if(s.keys.ArrowLeft)st.a-=2*dt;if(s.keys.ArrowRight)st.a+=2*dt;if(s.keys.ArrowUp){st.vx+=Math.cos(st.a)*95*dt;st.vy+=Math.sin(st.a)*95*dt}let damp=s.keys.ArrowDown?4:.18;st.vx*=Math.exp(-damp*dt);st.vy*=Math.exp(-damp*dt);st.x+=st.vx*dt;st.y+=st.vy*dt;if(st.x<25||st.x>455){st.x=s.clamp(st.x,25,455);st.vx*=-.4}if(st.y<80||st.y>455){st.y=s.clamp(st.y,80,455);st.vy*=-.4}let angle=Math.atan2(Math.sin(st.a+Math.PI/2),Math.cos(st.a+Math.PI/2));if(s.dist(st,{x:385,y:135})<31&&Math.hypot(st.vx,st.vy)<20&&Math.abs(angle)<.4)st.hold+=dt;else st.hold=0;if(st.hold>.8)s.win()},draw(){for(let i=0;i<35;i++)s.circle(i*97%480,70+i*53%400,1,'#607c6b');s.circle(385,135,48,'#3e654b');s.ctx.setLineDash([5,7]);s.ctx.strokeStyle=s.pal.lime;s.ctx.lineWidth=2;s.ctx.strokeRect(350,94,70,80);s.ctx.setLineDash([]);s.arrow(385,135,-Math.PI/2,s.pal.lime,13);if(s.keys.ArrowUp)s.star(st.x-Math.cos(st.a)*21,st.y-Math.sin(st.a)*21,9,s.pal.red);s.arrow(st.x,st.y,st.a,s.pal.gold,20);s.label('Скорость '+Math.round(Math.hypot(st.vx,st.vy))+'  ·  ↓ тормоз');s.text('Совмести положение и направление ↑',240,455,14,s.pal.muted)}}});
R('mastermind',s=>{const colors=[s.pal.red,s.pal.blue,s.pal.lime,s.pal.gold,'#c49ce6','#f0afdb'];let st={code:s.shuffle([0,1,2,3,4,5]).slice(0,4),guess:[0,0,0,0],selected:0,history:[]};function submit(){let exact=0,total=0;for(let i=0;i<4;i++)if(st.guess[i]===st.code[i])exact++;for(let c=0;c<6;c++)total+=Math.min(st.code.filter(v=>v===c).length,st.guess.filter(v=>v===c).length);st.history.push({guess:[...st.guess],exact,partial:total-exact});if(exact===4)s.win();else if(st.history.length===10)s.lose('Код не взломан. Золотые точки означают точное место, белые — другой порядок.') }return{state:st,tap(x,y){if(y>350&&y<405){let i=Math.floor((x-70)/65);if(i>=0&&i<4)st.selected=i}if(y>415&&y<465){let c=Math.floor((x-40)/65);if(c>=0&&c<6){st.guess[st.selected]=c;st.selected=(st.selected+1)%4}}},draw(){s.label(`Попытка ${Math.min(st.history.length+1,10)}/10  ·  четыре разных цвета`);st.history.forEach((r,j)=>{let y=72+j*26;s.text(j+1,48,y,12,s.pal.muted);r.guess.forEach((c,i)=>s.circle(90+i*49,y,10,colors[c]));for(let n=0;n<r.exact;n++)s.circle(320+n*14,y,4,s.pal.gold);for(let n=0;n<r.partial;n++)s.circle(320+(n+r.exact)*14,y,4,s.pal.white)});for(let i=0;i<4;i++){s.rect(70+i*65,355,56,48,st.selected===i?'#5b7a48':'#284236');s.circle(98+i*65,379,15,colors[st.guess[i]])}s.button(345,355,115,48,'Проверить',submit,'#5f7645');for(let i=0;i<6;i++){s.rect(40+i*65,420,55,42,'#304c3d');s.circle(67.5+i*65,441,14,colors[i])}}}});
R('domino',s=>{const path=[1,3,5,2,4,6,0,2];let st={tiles:s.shuffle(Array.from({length:7},(_,i)=>[path[i],path[i+1]])),chain:[],end:1};function choose(i){if(st.chain.some(c=>c.i===i))return;let [a,b]=st.tiles[i];if(a!==st.end&&b!==st.end)return;st.chain.push({i,from:st.end,to:a===st.end?b:a});st.end=st.chain.at(-1).to;if(st.chain.length===7)s.win()}return{state:st,tap(x,y){let i=Math.floor((x-30)/105)+Math.floor((y-225)/78)*4;if(y>225&&y<381&&i>=0&&i<7)choose(i)},draw(){s.label('Начни с 1 → используй все 7 костяшек');s.text('1'+st.chain.map(c=>' — '+c.to).join(''),240,130,25,s.pal.gold);st.tiles.forEach(([a,b],i)=>{let x=30+i%4*105,y=225+Math.floor(i/4)*78,used=st.chain.some(c=>c.i===i);s.rect(x,y,92,58,used?'#253d31':'#dce8c6',8);s.line(x+46,y+6,x+46,y+52,used?'#46634d':'#9cad89',2);s.text(a,x+23,y+29,23,used?'#54755a':s.pal.bg);s.text(b,x+69,y+29,23,used?'#54755a':s.pal.bg)});s.button(135,415,210,40,'Назад',()=>{st.chain.pop();st.end=st.chain.length?st.chain.at(-1).to:1})}}});
R('tangram',s=>{const targets=[{x:240,y:125,w:60,h:52,a:0},{x:240,y:220,w:76,h:110,a:0},{x:160,y:214,w:30,h:95,a:0},{x:320,y:214,w:30,h:95,a:0},{x:240,y:328,w:105,h:40,a:0}],colors=[s.pal.gold,s.pal.lime,s.pal.red,s.pal.blue,'#bba6e0'];let st={pieces:targets.map((t,i)=>({...t,x:[75,105,405,395,85][i],y:[110,375,105,390,255][i],a:(i%3+1)*Math.PI/2,locked:false})),selected:0,drag:null};function snap(i){let p=st.pieces[i],t=targets[i],a=Math.atan2(Math.sin(p.a),Math.cos(p.a));if(Math.hypot(p.x-t.x,p.y-t.y)<24&&Math.abs(a)<.15){p.x=t.x;p.y=t.y;p.a=0;p.locked=true;if(st.pieces.every(p=>p.locked))s.win()}}return{state:st,down(x,y){for(let i=4;i>=0;i--){let p=st.pieces[i],dx=x-p.x,dy=y-p.y,c=Math.cos(-p.a),sn=Math.sin(-p.a),u=dx*c-dy*sn,v=dx*sn+dy*c;if(!p.locked&&Math.abs(u)<p.w/2&&Math.abs(v)<p.h/2){st.selected=i;st.drag={i,dx,dy};break}}},move(x,y){if(st.drag){let p=st.pieces[st.drag.i];p.x=s.clamp(x-st.drag.dx,25,455);p.y=s.clamp(y-st.drag.dy,80,390)}},up(){if(st.drag)snap(st.drag.i);st.drag=null},draw(){targets.forEach((p,i)=>{s.ctx.strokeStyle=colors[i];s.ctx.lineWidth=2;s.ctx.setLineDash([5,5]);s.ctx.strokeRect(p.x-p.w/2,p.y-p.h/2,p.w,p.h);s.ctx.setLineDash([])});st.pieces.forEach((p,i)=>{s.ctx.save();s.ctx.translate(p.x,p.y);s.ctx.rotate(p.a);s.rect(-p.w/2,-p.h/2,p.w,p.h,colors[i],8);if(i===0){s.circle(-12,-4,5,s.pal.bg);s.circle(12,-4,5,s.pal.bg)}s.ctx.restore()});s.button(130,422,220,40,'Повернуть выбранную ↻',()=>{let p=st.pieces[st.selected];if(!p.locked){p.a+=Math.PI/2;snap(st.selected)}});s.label(`Детали на месте: ${st.pieces.filter(p=>p.locked).length}/5`)}}});
function clipHalf(poly,a,b){let out=[];for(let i=0;i<poly.length;i++){let p=poly[i],q=poly[(i+1)%poly.length],cp=(b.x-a.x)*(p.y-a.y)-(b.y-a.y)*(p.x-a.x),cq=(b.x-a.x)*(q.y-a.y)-(b.y-a.y)*(q.x-a.x);if(cp>=0)out.push(p);if((cp>=0)!==(cq>=0)){let t=cp/(cp-cq);out.push({x:p.x+(q.x-p.x)*t,y:p.y+(q.y-p.y)*t})}}return out}
