R('boss',s=>{let st={x:240,y:385,hp:5,boss:18,shots:[],zones:[],cast:2,cool:0,inv:0};return{state:st,update(dt){mover(s,st,170,dt);st.cool-=dt;st.inv-=dt;st.cast-=dt;if(st.cast<=0){st.cast=2.5;st.zones.push({x:st.x,y:st.y,t:1.1})}for(let z of st.zones){z.t-=dt;if(z.t<0&&z.t>-.2&&st.inv<=0&&s.dist(st,z)<58){st.hp--;st.inv=1.4;if(st.hp<=0)s.lose('Хранитель победил. Уходи из кругов до вспышки и атакуй без щита.')}}st.zones=st.zones.filter(z=>z.t>-.4);if(s.keys.Space&&st.cool<=0){st.cool=.38;let dx=240-st.x,dy=130-st.y,d=Math.hypot(dx,dy);st.shots.push({x:st.x,y:st.y,vx:dx/d*370,vy:dy/d*370})}for(let p of st.shots){p.x+=p.vx*dt;p.y+=p.vy*dt;if(s.dist(p,{x:240,y:130})<44){p.done=true;if(s.t%6>2){st.boss--;if(st.boss<=0)s.win()}}}st.shots=st.shots.filter(p=>!p.done&&p.y>60&&p.x>0&&p.x<480)},draw(){for(let z of st.zones){s.circle(z.x,z.y,58,z.t<0?'#ce8b66':'#6c3d36');s.circle(z.x,z.y,Math.max(3,54*(1-z.t/1.1)),'#925447')}s.circle(240,130,42,'#a282bd');s.text('♛',240,130,43,s.pal.bg);if(s.t%6<=2){s.ctx.strokeStyle=s.pal.blue;s.ctx.lineWidth=7;s.ctx.beginPath();s.ctx.arc(240,130,52,0,Math.PI*2);s.ctx.stroke()}s.rect(135,70,210*Math.max(0,st.boss)/18,7,s.pal.red,2);for(let p of st.shots)s.circle(p.x,p.y,5,s.pal.gold);s.cat(st.x,st.y,16,st.inv>0?s.pal.red:s.pal.lime);s.label(`${'♥'.repeat(Math.max(0,st.hp))}  ·  ${s.t%6<=2?'ЩИТ: уклоняйся':'ЩИТ ОТКРЫТ: атакуй!'}`)}}});
